def _collapse_widths(
    cls,
    widths: List[int],
    wrapable: List[bool],
    max_width: int,
    minimums: Optional[List[int]] = None,
) -> List[int]:
    """Reduce widths so that the total is under max_width.

    Args:
        widths (List[int]): List of widths.
        wrapable (List[bool]): List of booleans that indicate if a column may shrink.
        max_width (int): Maximum width to reduce to.
        minimums (Optional[List[int]]): Minimum width for each column. A column
            is never reduced below its minimum. Defaults to zero for all columns.

    Returns:
        List[int]: A new list of widths.
    """
    if minimums is None:
        minimums = [0] * len(widths)
    total_width = sum(widths)
    excess_width = total_width - max_width
    if any(wrapable):
        while total_width and excess_width > 0:
            # A column can only shrink if it is wrapable and above its minimum.
            shrinkable = [
                allow_wrap and width > minimum
                for width, allow_wrap, minimum in zip(widths, wrapable, minimums)
            ]
            if not any(shrinkable):
                break
            max_column = max(
                width for width, can_shrink in zip(widths, shrinkable) if can_shrink
            )
            second_max_column = max(
                width if can_shrink and width != max_column else 0
                for width, can_shrink in zip(widths, shrinkable)
            )
